  mul(x) {
    // If x is a number, perform scalar multiplication
    if (typeof x === 'number') {
      const resultRows = [];
      for (let i = 0; i < this._rows.length; i++) {
        const row = [];
        for (let j = 0; j < this._rows[0].length; j++) {
          row.push(this.get(i, j) * x);
        }
        resultRows.push(row);
      }
      return new Matrix(resultRows);
    }

    // If x is a Matrix, perform matrix multiplication
    if (x instanceof Matrix) {
      const shape1 = this.shape();
      const shape2 = x.shape();

      // Check if inner dimensions match
      if (shape1[1] !== shape2[0]) {
        throw new Error("Inner dimensions do not match for matrix multiplication");
      }

      // Perform matrix multiplication
      const resultRows = [];
      for (let i = 0; i < shape1[0]; i++) {
        const row = [];
        for (let j = 0; j < shape2[1]; j++) {
          let sum = 0;
          for (let k = 0; k < shape1[1]; k++) {
            sum += this.get(i, k) * x.get(k, j);
          }
          row.push(sum);
        }
        resultRows.push(row);
      }
      return new Matrix(resultRows);
    }

    // If x is neither a number nor a Matrix, throw an error
    throw new Error("Operand must be a number or a Matrix");
  }
}

