// s5_expr.js - Expression evaluator with + - * / precedence and error handling

function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()^]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Parse and evaluate the expression
    function parseExpression() {
        let result = parseTerm();

        while (true) {
            const char = expr[pos];
            if (char === '+') {
                pos++;
                result += parseTerm();
            } else if (char === '-') {
                pos++;
                result -= parseTerm();
            } else {
                break;
            }
        }

        return result;
    }

    function parsePower() {
        let result = parseFactor();

        // Handle right-associative power operations
        if (expr[pos] === '^') {
            pos++;
            const exponent = parsePower();  // Right-associative: 2^3^2 = 2^(3^2) = 2^9 = 512
            result = Math.pow(result, exponent);
        }

        return result;
    }

    function parseTerm() {
        let result = parsePower();

        while (true) {
            const char = expr[pos];
            if (char === '*') {
                pos++;
                result *= parsePower();
            } else if (char === '/') {
                pos++;
                const divisor = parsePower();
                if (divisor === 0) {
                    throw new Error('Division by zero');
                }
                result /= divisor;
            } else {
                break;
            }
        }

        return result;
    }

    function parseFactor() {
        if (expr[pos] === '(') {
            pos++;
            const result = parseExpression();
            if (expr[pos] !== ')') {
                throw new Error('Missing closing parenthesis');
            }
            pos++;
            return result;
        } else if (expr[pos] === '-') {
            pos++;
            // For unary minus, we need to handle it properly with precedence
            // The unary minus should apply to the next factor, but we need to make sure
            // it's not applied to a factor that's already been processed
            return -parsePower();  // Apply unary minus to the power result
        } else {
            return parseNumber();
        }
    }

    function parseNumber() {
        let start = pos;

        // Handle decimal numbers
        while (pos < expr.length && (/\d/.test(expr[pos]) || expr[pos] === '.')) {
            pos++;
        }

        if (start === pos) {
            throw new Error('Invalid number');
        }

        const numStr = expr.substring(start, pos);
        const num = parseFloat(numStr);

        if (isNaN(num)) {
            throw new Error('Invalid number');
        }

        return num;
    }

    let pos = 0;
    const result = parseExpression();

    // Check if we consumed the entire expression
    if (pos < expr.length) {
        throw new Error('Invalid expression');
    }

    return result;
}

