get(key) {
  if (!this.map.has(key)) {
    return undefined;
  }
  // Move to end to mark as recently used
  const value = this.map.get(key);
  this.map.delete(key);
  this.map.set(key, value);
  return value;
}

peek(key) {
  if (!this.map.has(key)) {
    return undefined;
  }
  // Just return the value without marking as recently used
  return this.map.get(key);
}

