multiply(other) {
  // Check if other is a Matrix
  if (!(other instanceof Matrix)) {
    throw new Error("Operand must be a Matrix");
  }

  // Get dimensions
  const shape1 = this.shape();
  const shape2 = other.shape();
  const rows1 = shape1[0];
  const cols1 = shape1[1];
  const rows2 = shape2[0];
  const cols2 = shape2[1];

  // Check if multiplication is possible
  if (cols1 !== rows2) {
    throw new Error("Matrix dimensions incompatible for multiplication");
  }

  // Perform multiplication
  const resultRows = [];
  for (let i = 0; i < rows1; i++) {
    const row = [];
    for (let j = 0; j < cols2; j++) {
      let sum = 0;
      for (let k = 0; k < cols1; k++) {
        sum += this.get(i, k) * other.get(k, j);
      }
      row.push(sum);
    }
    resultRows.push(row);
  }

  return new Matrix(resultRows);
}

