def reachable(self, a):
    """Return the sorted list of nodes reachable from a by one or more edges.

class Graph:
    def __init__(self):
        self._nodes = set()
        self._edges = {}

    def add_node(self, n):
        self._nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if weight <= 0:
            raise ValueError("Edge weight must be positive")
        self.add_node(a)
        self.add_node(b)
        if a not in self._edges:
            self._edges[a] = []
        self._edges[a].append((b, weight))

    def nodes(self):
        return sorted(list(self._nodes))

    def neighbors(self, a):
        if a not in self._edges:
            return []
        return sorted(self._edges[a], key=lambda x: x[0])

    def bfs(self, start):
        """Return the BFS traversal starting from start node."""
        if start not in self._nodes:
            raise KeyError(f"Start node '{start}' not in graph")
        visited = set()
        queue = [start]
        result = []

        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor, _ in self.neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)
        return result

    def shortest_path(self, a, b):
        """Return the shortest path from node a to node b using Dijkstra's algorithm.

        Args:
            a: start node
            b: end node

        Returns:
            tuple: (cost, [a, ..., b]) for the cheapest path, or None if b cannot be reached

        Raises:
            KeyError: if either node is not in the graph
        """
        if a not in self._nodes:
            raise KeyError(f"Start node '{a}' not in graph")
        if b not in self._nodes:
            raise KeyError(f"End node '{b}' not in graph")

        # Dijkstra's algorithm
        distances = {node: float('inf') for node in self._nodes}
        distances[a] = 0
        previous = {}
        unvisited = set(self._nodes)

        while unvisited:
            # Get node with minimum distance
            current = min(unvisited, key=lambda node: distances[node])

            # If we can't reach b, stop
            if distances[current] == float('inf'):
                break

            # If we reached the target, we're done
            if current == b:
                break

            unvisited.remove(current)

            # Update distances to neighbors
            for neighbor, weight in self.neighbors(current):
                if neighbor in unvisited:
                    new_distance = distances[current] + weight
                    if new_distance < distances[neighbor]:
                        distances[neighbor] = new_distance
                        previous[neighbor] = current

        # If we never reached b, return None
        if b not in distances or distances[b] == float('inf'):
            return None

        # Reconstruct path
        path = []
        current = b
        while current in previous:
            path.append(current)
            current = previous[current]
        path.append(a)
        path.reverse()

        return (distances[b], path)

    def has_cycle(self):
        """Return True if the graph has a directed cycle, False otherwise.

        An edge from a node to itself (a self-loop) counts as a cycle.
        """
        # Track visited nodes and recursion stack for DFS
        visited = set()
        rec_stack = set()

        def dfs(node):
            if node not in visited:
                visited.add(node)
                rec_stack.add(node)

                # Check all neighbors
                for neighbor, _ in self.neighbors(node):
                    # If neighbor is in recursion stack, we found a cycle
                    if neighbor in rec_stack:
                        return True
                    # If neighbor leads to cycle, we found a cycle
                    if dfs(neighbor):
                        return True

                # Remove node from recursion stack
                rec_stack.remove(node)

            return False

        # Check for cycles starting from each node
        for node in self.nodes():
            if dfs(node):
                return True

        return False

    def topo_order(self):
        """Return the nodes in topological order.

        Returns:
            list: Nodes in topological order, with ties broken by smallest node ID

        Raises:
            ValueError: If the graph has a cycle
        """
        # Calculate in-degrees for all nodes
        in_degree = {node: 0 for node in self._nodes}
        for node in self._nodes:
            for neighbor, _ in self.neighbors(node):
                in_degree[neighbor] += 1

        # Initialize queue with all nodes with in-degree 0
        # Using a list and sorting to ensure we always pick the smallest
        queue = [node for node in self._nodes if in_degree[node] == 0]
        result = []

        while queue:
            # Sort to ensure we always pick the smallest node
            queue.sort()
            node = queue.pop(0)
            result.append(node)

            # Reduce in-degree of neighbors
            for neighbor, _ in self.neighbors(node):
                in_degree[neighbor] -= 1
                # If in-degree becomes 0, add to queue
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # If result doesn't contain all nodes, there's a cycle
        if len(result) != len(self._nodes):
            raise ValueError("Graph has a cycle")

        return result

    def reachable(self, a):
        """Return the sorted list of nodes reachable from a by one or more edges.

        Args:
            a: start node

        Returns:
            list: sorted list of nodes reachable from a

        Raises:
            KeyError: if node a is not in the graph
        """
        if a not in self._nodes:
            raise KeyError(f"Start node '{a}' not in graph")

        # Use BFS to find all reachable nodes
        visited = set()
        queue = [a]
        result = []

        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor, _ in self.neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)

        # Return sorted list of reachable nodes
        return sorted(result)

class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || null;
    this.now = options.now || (() => Date.now());
    this.onEvict = options.onEvict || null;
    // Stats tracking
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
    this.expirations = 0;
  }

set(key, value, options = {}) {
  if (this.map.has(key)) {
    // Update existing key
    this.map.delete(key);
  } else if (this.map.size >= this.capacity) {
    // Remove least recently used item
    const firstKey = this.map.keys().next().value;
    const entry = this.map.get(firstKey);
    this.map.delete(firstKey);
    if (this.onEvict) {
      this.onEvict(firstKey, entry.value, 'lru');
    }
  }

  const ttl = options.ttl !== undefined ? options.ttl : this.ttl;
  const expiry = ttl !== null ? this.now() + ttl : null;

  this.map.set(key, { value, expiry });
}

get(key) {
  if (!this.map.has(key)) {
    this.misses++;
    return undefined;
  }
  // Check if entry has expired
  const entry = this.map.get(key);
  if (entry.expiry !== null && this.now() > entry.expiry) {
    this.map.delete(key);
    this.expirations++;
    if (this.onEvict) {
      this.onEvict(key, entry.value, 'expired');
    }
    return undefined;
  }
  // Move to end to mark as recently used
  const value = entry.value;
  this.map.delete(key);
  this.map.set(key, entry);
  this.hits++;
  return value;
}

delete(key) {
  const deleted = this.map.delete(key);
  if (deleted && this.onEvict) {
    const entry = this.map.get(key);
    if (entry) {
      this.onEvict(key, entry.value, 'deleted');
    }
  }
  return deleted;
}

clear() {
  if (this.onEvict) {
    for (const [key, entry] of this.map.entries()) {
      this.onEvict(key, entry.value, 'deleted');
    }
  }
  this.map.clear();
}

