  solve(b) {
    // Check if matrix is square
    const shape = this.shape();
    const n = shape[0];
    if (shape[0] !== shape[1]) {
      throw new Error("Matrix must be square to solve Ax = b");
    }

    // Check if b has the correct length
    if (!Array.isArray(b) || b.length !== n) {
      throw new Error("b must be an array with the same length as the matrix rows");
    }

    // Create augmented matrix [A|b]
    const augmented = [];
    for (let i = 0; i < n; i++) {
      const row = [...this._rows[i], b[i]];
      augmented.push(row);
    }

    // Forward elimination
    for (let i = 0; i < n; i++) {
      // Find pivot
      let maxRow = i;
      for (let k = i + 1; k < n; k++) {
        if (Math.abs(augmented[k][i]) > Math.abs(augmented[maxRow][i])) {
          maxRow = k;
        }
      }

      // Swap rows
      if (maxRow !== i) {
        [augmented[i], augmented[maxRow]] = [augmented[maxRow], augmented[i]];
      }

      // Check for singular matrix
      if (Math.abs(augmented[i][i]) < 1e-10) {
        throw new Error("Matrix is singular, cannot solve Ax = b");
      }

      // Eliminate column
      for (let k = i + 1; k < n; k++) {
        const factor = augmented[k][i] / augmented[i][i];
        for (let j = i; j <= n; j++) {
          augmented[k][j] -= factor * augmented[i][j];
        }
      }
    }

    // Back substitution
    const x = new Array(n);
    for (let i = n - 1; i >= 0; i--) {
      x[i] = augmented[i][n];
      for (let j = i + 1; j < n; j++) {
        x[i] -= augmented[i][j] * x[j];
      }
      x[i] /= augmented[i][i];
    }

    return x;
  }
}

