// Add snapshot and restore functions
function snapshot(library, cache, key) {
  const data = JSON.stringify(library.toJSON());
  cache.set(key, data);
  return data;
}

function restore(cache, key) {
  const data = cache.get(key);
  if (data === undefined) {
    return null;
  }
  return Library.fromJSON(JSON.parse(data));
}

